def wave(x0, x1, y, amp, c, w=4, step=8, grow=False):
    pts = [(x, round(y + amp * (0.3 + 0.7 * (x - x0) / (x1 - x0) if grow else 1) * math.sin((x - x0) / 9))) for x in range(x0, x1 + 1, step)]
    return polyline(pts, w, c)


def fishy(cx, cy, c):
    return [O(cx, cy, 44, 16, c, 14), P([(cx + 40, cy), (cx + 62, cy - 16), (cx + 62, cy + 16)], c), O(cx - 26, cy - 4, 4, 4, IN)]


