if __name__ == "__main__":
    assert len(NOUNS) == 72, len(NOUNS)
    taken = [w for w in NOUNS if (base.ASSETS / f"word_{w}_plate.imageset").exists()]
    assert not taken, f"would overwrite existing imagesets: {taken}"
    base.WORDS = NOUNS
    if len(sys.argv) > 2 and sys.argv[1] == "json":
        import json
        print(json.dumps(base.json_for(sys.argv[2]), separators=(",", ":")))
    else:
        base.main()
